namespace AlxorCore.Documentos.Infraestructura;

/// <summary>
/// Emblema por defecto del ticket (cesta de la compra, en negro) cuando la empresa no tiene logo.
/// PNG con fondo transparente, incrustado para que el PDF sea autónomo.
/// </summary>
internal static class EmblemaTicket
{
    private const string CestaBase64 =
        "";

    public static byte[] Cesta { get; } = System.Convert.FromBase64String(CestaBase64);
}
